  function translate(message, language) {
    const table = normalizedTranslations[language];
    if (!table || !message) return "";
    const source = String(message);
    const values = [];
    let template = "";
    let cursor = 0;
    while (cursor < source.length) {
      const start = source.indexOf("<suggestion>", cursor);
      if (start < 0) { template += source.slice(cursor); break; }
      const end = source.indexOf("</suggestion>", start + 12);
      if (end < 0) { template += source.slice(cursor); break; }
      values.push(source.slice(start + 12, end));
      template += source.slice(cursor, start) + `<suggestion>{suggestion${values.length}}</suggestion>`;
      cursor = end + 13;
    }
    const translated = table[template] || translateDynamic(template, language);
    if (!translated) return "";
    return translated.replace(/\{suggestion(\d+)\}/gu, (_match, index) => values[Number(index) - 1] || "");
  }

  globalThis.CorrectorLocalEnglishExplanationTranslations = Object.freeze({ translate });
